const pptxgen = require("pptxgenjs");

// ============================================================
// Color Palette: "Midnight Executive" adapted for data-forward tech
// Primary: 1E2761 (navy), Secondary: CADCFC (ice blue), Accent: FFFFFF (white)
// Additional: 0D9488 (teal for positive), DC2626 (red for negative), 64748B (slate for muted)
// ============================================================
const COLORS = {
  navy: "1E2761",
  iceBlue: "CADCFC",
  white: "FFFFFF",
  teal: "0D9488",
  red: "DC2626",
  slate: "64748B",
  lightGray: "F1F5F9",
  darkText: "1E293B",
  mutedText: "64748B",
  chartBar: "1E2761",
  chartBarSecondary: "CADCFC",
  chartPositive: "0D9488",
  chartNegative: "DC2626",
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "TIOBE Data Analysis";
pres.title = "TIOBE Index March 2026: Programming Language Popularity Rankings and Trends";
pres.subject = "Programming Language Popularity Trends";

// ============================================================
// Helper: fresh shadow factory
// ============================================================
function makeShadow(opts = {}) {
  return {
    type: "outer",
    color: "000000",
    blur: 6,
    offset: 2,
    angle: 135,
    opacity: 0.12,
    ...opts,
  };
}

// ============================================================
// Slide 1: Title
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.navy };

  // Decorative top-right shape
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.5, y: 0, w: 2.5, h: 5.625,
    fill: { color: COLORS.iceBlue, transparency: 8 },
  });

  // Accent bar left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.6, w: 0.08, h: 2.8,
    fill: { color: COLORS.iceBlue },
  });

  // Title
  slide.addText("TIOBE Index March 2026: How 20+ Search Engines Rank the World's Programming Languages", {
    x: 0.8, y: 1.5, w: 8.2, h: 1.6,
    fontSize: 32, fontFace: "Arial Black", color: COLORS.white,
    bold: true, align: "left", valign: "top", margin: 0,
  });

  // Subtitle / methodology
  slide.addText("Ratings calculated from search-engine hit counts across Google, Bing, Wikipedia, Amazon, and 20+ other sites — reflecting global discussion and demand for programming languages.", {
    x: 0.8, y: 3.3, w: 8.0, h: 1.0,
    fontSize: 14, fontFace: "Calibri", color: COLORS.iceBlue,
    align: "left", valign: "top", margin: 0,
  });

  // Footer meta
  slide.addText("Source: TIOBE Programming Community Index  |  Captured: April 2026", {
    x: 0.5, y: 5.1, w: 9, h: 0.3,
    fontSize: 10, fontFace: "Calibri", color: COLORS.iceBlue,
    align: "left", valign: "middle", margin: 0,
  });
}

// ============================================================
// Slide 2: Top 20 Rankings (table + bar chart)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.white };

  // Title
  slide.addText("Python Holds #1 at 21.25% but C Surges to #2 with the Largest Gain", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 26, fontFace: "Arial Black", color: COLORS.navy,
    bold: true, align: "left", valign: "middle", margin: 0,
  });

  // Subtitle
  slide.addText("Top 20 Programming Languages — March 2026", {
    x: 0.5, y: 0.95, w: 9, h: 0.3,
    fontSize: 12, fontFace: "Calibri", color: COLORS.slate,
    align: "left", valign: "middle", margin: 0,
  });

  // Table data
  const tableRows = [
    [
      { text: "Rank", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "Prev", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "Language", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "left" } },
      { text: "Rating", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "YoY Change", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
    ],
    ["1", "1", "Python", "21.25%", "-2.59%"],
    ["2", "4", "C", "11.55%", "+2.02%"],
    ["3", "2", "C++", "8.18%", "-2.90%"],
    ["4", "3", "Java", "7.99%", "-2.37%"],
    ["5", "5", "C#", "6.36%", "+1.49%"],
    ["6", "6", "JavaScript", "3.45%", "-0.01%"],
    ["7", "9", "Visual Basic", "2.50%", "-0.02%"],
    ["8", "8", "SQL", "2.00%", "-0.57%"],
    ["9", "16", "R", "1.88%", "+0.94%"],
    ["10", "10", "Delphi/Object Pascal", "1.80%", "-0.36%"],
    ["11", "24", "Perl", "1.75%", "+1.05%"],
    ["12", "12", "Scratch", "1.63%", "-0.03%"],
    ["13", "11", "Fortran", "1.45%", "-0.25%"],
    ["14", "14", "Rust", "1.31%", "+0.09%"],
    ["15", "15", "MATLAB", "1.29%", "+0.31%"],
    ["16", "7", "Go", "1.29%", "-1.49%"],
    ["17", "17", "Assembly language", "1.29%", "+0.42%"],
    ["18", "13", "PHP", "1.23%", "-0.25%"],
    ["19", "18", "Ada", "1.10%", "+0.25%"],
    ["20", "26", "Swift", "1.04%", "+0.44%"],
  ];

  // Colorize YoY cells
  const coloredRows = tableRows.map((row, idx) => {
    if (idx === 0) return row;
    const yoy = row[4];
    const yoyColor = yoy.startsWith("+") ? COLORS.teal : (yoy.startsWith("-") ? COLORS.red : COLORS.darkText);
    const bgColor = idx % 2 === 0 ? COLORS.lightGray : COLORS.white;
    return [
      { text: row[0], options: { align: "center", fill: { color: bgColor }, color: COLORS.darkText } },
      { text: row[1], options: { align: "center", fill: { color: bgColor }, color: COLORS.darkText } },
      { text: row[2], options: { align: "left", fill: { color: bgColor }, color: COLORS.darkText } },
      { text: row[3], options: { align: "center", fill: { color: bgColor }, color: COLORS.darkText } },
      { text: row[4], options: { align: "center", fill: { color: bgColor }, color: yoyColor, bold: true } },
    ];
  });

  slide.addTable(coloredRows, {
    x: 0.5, y: 1.35, w: 5.4, h: 3.8,
    border: { pt: 0.5, color: "E2E8F0" },
    colW: [0.7, 0.7, 2.4, 0.8, 0.8],
    fontSize: 9, fontFace: "Calibri",
    color: COLORS.darkText,
  });

  // Mini bar chart: top 8 languages ratings
  slide.addChart(pres.charts.BAR, [{
    name: "Rating",
    labels: ["Python", "C", "C++", "Java", "C#", "JS", "VB", "SQL"],
    values: [21.25, 11.55, 8.18, 7.99, 6.36, 3.45, 2.50, 2.00],
  }], {
    x: 6.2, y: 1.35, w: 3.8, h: 3.8,
    barDir: "col",
    chartColors: [COLORS.navy],
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.slate,
    valAxisLabelColor: COLORS.slate,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.darkText,
    dataLabelFontSize: 9,
    showLegend: false,
    title: "Top 8 Language Ratings (%)",
    titleFontSize: 11,
    titleColor: COLORS.navy,
    titleBold: true,
  });

  // Footer
  slide.addText("Source: TIOBE Index, March 2026  |  Top 4 languages hold 48.97% of total index", {
    x: 0.5, y: 5.25, w: 9, h: 0.25,
    fontSize: 10, fontFace: "Calibri", color: COLORS.slate,
    align: "left", valign: "middle", margin: 0,
  });
}

// ============================================================
// Slide 3: Biggest Movers (gainers vs losers)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.white };

  // Title
  slide.addText("Perl Jumps 13 Spots, R Climbs 7, and Go Drops 9 — The Biggest Rank Shifts of 2026", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 24, fontFace: "Arial Black", color: COLORS.navy,
    bold: true, align: "left", valign: "middle", margin: 0,
  });

  // Subtitle
  slide.addText("Rank changes from March 2025 to March 2026", {
    x: 0.5, y: 0.95, w: 9, h: 0.25,
    fontSize: 12, fontFace: "Calibri", color: COLORS.slate,
    align: "left", valign: "middle", margin: 0,
  });

  // Gainers column header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.35, w: 4.4, h: 0.45,
    fill: { color: COLORS.teal },
  });
  slide.addText("▲ Gainers", {
    x: 0.5, y: 1.35, w: 4.4, h: 0.45,
    fontSize: 14, fontFace: "Arial Black", color: COLORS.white,
    bold: true, align: "center", valign: "middle", margin: 0,
  });

  // Gainers data cards
  const gainers = [
    { lang: "Perl", from: 24, to: 11, change: "+13", pct: "+1.05%" },
    { lang: "R", from: 16, to: 9, change: "+7", pct: "+0.94%" },
    { lang: "Swift", from: 26, to: 20, change: "+6", pct: "+0.44%" },
    { lang: "C", from: 4, to: 2, change: "+2", pct: "+2.02%" },
  ];

  gainers.forEach((g, i) => {
    const y = 1.9 + i * 0.85;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y, w: 4.4, h: 0.75,
      fill: { color: COLORS.lightGray },
      shadow: makeShadow(),
    });
    // Accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y, w: 0.08, h: 0.75,
      fill: { color: COLORS.teal },
    });
    slide.addText(`${g.lang}`, {
      x: 0.7, y, w: 1.8, h: 0.75,
      fontSize: 14, fontFace: "Arial Black", color: COLORS.darkText,
      bold: true, align: "left", valign: "middle", margin: 0,
    });
    slide.addText(`${g.from} → ${g.to}`, {
      x: 2.4, y, w: 1.2, h: 0.75,
      fontSize: 12, fontFace: "Calibri", color: COLORS.darkText,
      align: "center", valign: "middle", margin: 0,
    });
    slide.addText(`${g.change}  (${g.pct})`, {
      x: 3.5, y, w: 1.2, h: 0.75,
      fontSize: 12, fontFace: "Calibri", color: COLORS.teal,
      bold: true, align: "right", valign: "middle", margin: 0,
    });
  });

  // Losers column header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.35, w: 4.4, h: 0.45,
    fill: { color: COLORS.red },
  });
  slide.addText("▼ Losers", {
    x: 5.3, y: 1.35, w: 4.4, h: 0.45,
    fontSize: 14, fontFace: "Arial Black", color: COLORS.white,
    bold: true, align: "center", valign: "middle", margin: 0,
  });

  // Losers data cards
  const losers = [
    { lang: "Go", from: 7, to: 16, change: "-9", pct: "-1.49%" },
    { lang: "C++", from: 2, to: 3, change: "-1", pct: "-2.90%" },
    { lang: "Java", from: 3, to: 4, change: "-1", pct: "-2.37%" },
    { lang: "PHP", from: 13, to: 18, change: "-5", pct: "-0.25%" },
  ];

  losers.forEach((l, i) => {
    const y = 1.9 + i * 0.85;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y, w: 4.4, h: 0.75,
      fill: { color: COLORS.lightGray },
      shadow: makeShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.3, y, w: 0.08, h: 0.75,
      fill: { color: COLORS.red },
    });
    slide.addText(`${l.lang}`, {
      x: 5.5, y, w: 1.8, h: 0.75,
      fontSize: 14, fontFace: "Arial Black", color: COLORS.darkText,
      bold: true, align: "left", valign: "middle", margin: 0,
    });
    slide.addText(`${l.from} → ${l.to}`, {
      x: 7.2, y, w: 1.2, h: 0.75,
      fontSize: 12, fontFace: "Calibri", color: COLORS.darkText,
      align: "center", valign: "middle", margin: 0,
    });
    slide.addText(`${l.change}  (${l.pct})`, {
      x: 8.3, y, w: 1.2, h: 0.75,
      fontSize: 12, fontFace: "Calibri", color: COLORS.red,
      bold: true, align: "right", valign: "middle", margin: 0,
    });
  });

  // Insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.0, w: 9.2, h: 0.45,
    fill: { color: COLORS.navy },
  });
  slide.addText("Insight: Legacy languages (Perl, R) show surprising resilience, while Go suffers its sharpest decline — possibly displaced by Rust in systems programming.", {
    x: 0.5, y: 5.0, w: 9.2, h: 0.45,
    fontSize: 11, fontFace: "Calibri", color: COLORS.white,
    align: "center", valign: "middle", margin: 0,
  });
}

// ============================================================
// Slide 4: Historical Trend (long-term table + key narrative)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.white };

  // Title
  slide.addText("From Lisp at #2 in 1986 to Python at #1 in 2026: How Language Rankings Shifted Over Time", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 22, fontFace: "Arial Black", color: COLORS.navy,
    bold: true, align: "left", valign: "middle", margin: 0,
  });

  // Subtitle
  slide.addText("Rank positions across four decades (1986–2026)", {
    x: 0.5, y: 0.95, w: 9, h: 0.25,
    fontSize: 12, fontFace: "Calibri", color: COLORS.slate,
    align: "left", valign: "middle", margin: 0,
  });

  // Historical table
  const histRows = [
    [
      { text: "Language", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "left" } },
      { text: "2026", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "2021", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "2016", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "2011", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "2006", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "2001", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "1996", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "1991", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "1986", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
    ],
    ["Python", "1", "3", "5", "7", "8", "26", "17", "—", "—"],
    ["C", "2", "1", "2", "2", "2", "1", "1", "1", "1"],
    ["C++", "3", "4", "3", "3", "3", "2", "2", "2", "9"],
    ["Java", "4", "2", "1", "1", "1", "3", "31", "—", "—"],
    ["C#", "5", "5", "4", "5", "7", "11", "—", "—", "—"],
    ["JavaScript", "6", "7", "8", "10", "10", "8", "33", "—", "—"],
    ["Go", "10", "11", "60", "16", "—", "—", "—", "—", "—"],
    ["Ada", "14", "36", "25", "22", "16", "18", "6", "10", "3"],
    ["Lisp", "26", "34", "26", "13", "14", "19", "8", "4", "2"],
  ];

  const coloredHist = histRows.map((row, idx) => {
    if (idx === 0) return row;
    const bgColor = idx % 2 === 0 ? COLORS.lightGray : COLORS.white;
    return row.map((cell, cidx) => {
      const isDash = cell === "—";
      return {
        text: cell,
        options: {
          align: cidx === 0 ? "left" : "center",
          fill: { color: bgColor },
          color: isDash ? COLORS.slate : COLORS.darkText,
          bold: cidx === 0,
        },
      };
    });
  });

  slide.addTable(coloredHist, {
    x: 0.5, y: 1.3, w: 9.2, h: 2.6,
    border: { pt: 0.5, color: "E2E8F0" },
    colW: [1.4, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8, 0.8],
    fontSize: 10, fontFace: "Calibri",
    color: COLORS.darkText,
  });

  // Key narrative callouts (3 columns)
  const callouts = [
    { title: "Python's Meteoric Rise", body: "Unranked before 1991 → #1 by 2026. Peaked above 25% before settling at 21.25%." },
    { title: "Java's Long Decline", body: "Dominated 2005–2018 at 25%+. Now under 8% and falling steadily." },
    { title: "C's Unmatched Resilience", body: "Only language in the top 2 across all nine measurement points since 1986." },
  ];

  callouts.forEach((c, i) => {
    const x = 0.5 + i * 3.2;
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: 4.1, w: 2.9, h: 1.2,
      fill: { color: COLORS.lightGray },
      shadow: makeShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: 4.1, w: 2.9, h: 0.08,
      fill: { color: COLORS.navy },
    });
    slide.addText(c.title, {
      x: x + 0.1, y: 4.25, w: 2.7, h: 0.35,
      fontSize: 11, fontFace: "Arial Black", color: COLORS.navy,
      bold: true, align: "left", valign: "top", margin: 0,
    });
    slide.addText(c.body, {
      x: x + 0.1, y: 4.55, w: 2.7, h: 0.7,
      fontSize: 10, fontFace: "Calibri", color: COLORS.darkText,
      align: "left", valign: "top", margin: 0,
    });
  });

  // Footer
  slide.addText("Source: TIOBE Index historical data (1986–2026)", {
    x: 0.5, y: 5.35, w: 9, h: 0.2,
    fontSize: 10, fontFace: "Calibri", color: COLORS.slate,
    align: "left", valign: "middle", margin: 0,
  });
}

// ============================================================
// Slide 5: Hall of Fame
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.white };

  // Title
  slide.addText("Python Wins Language of the Year 6 Times — More Than Any Other Language", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 24, fontFace: "Arial Black", color: COLORS.navy,
    bold: true, align: "left", valign: "middle", margin: 0,
  });

  // Subtitle
  slide.addText("TIOBE 'Programming Language of the Year' winners (largest annual rating gain)", {
    x: 0.5, y: 0.95, w: 9, h: 0.25,
    fontSize: 12, fontFace: "Calibri", color: COLORS.slate,
    align: "left", valign: "middle", margin: 0,
  });

  // Winners table
  const hofRows = [
    [
      { text: "Year", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "Winner", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "left" } },
      { text: "Year", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "Winner", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "left" } },
    ],
    [
      { text: "2025", options: { align: "center", fill: { color: COLORS.lightGray }, color: COLORS.darkText } },
      { text: "C#", options: { align: "left", fill: { color: COLORS.lightGray }, color: COLORS.darkText, bold: true } },
      { text: "2019", options: { align: "center", fill: { color: COLORS.white }, color: COLORS.darkText } },
      { text: "C", options: { align: "left", fill: { color: COLORS.white }, color: COLORS.darkText, bold: true } },
    ],
    [
      { text: "2024", options: { align: "center", fill: { color: COLORS.white }, color: COLORS.darkText } },
      { text: "Python", options: { align: "left", fill: { color: COLORS.white }, color: COLORS.teal, bold: true } },
      { text: "2018", options: { align: "center", fill: { color: COLORS.lightGray }, color: COLORS.darkText } },
      { text: "Python", options: { align: "left", fill: { color: COLORS.lightGray }, color: COLORS.teal, bold: true } },
    ],
    [
      { text: "2023", options: { align: "center", fill: { color: COLORS.lightGray }, color: COLORS.darkText } },
      { text: "C#", options: { align: "left", fill: { color: COLORS.lightGray }, color: COLORS.darkText, bold: true } },
      { text: "2016", options: { align: "center", fill: { color: COLORS.white }, color: COLORS.darkText } },
      { text: "Go", options: { align: "left", fill: { color: COLORS.white }, color: COLORS.darkText, bold: true } },
    ],
    [
      { text: "2022", options: { align: "center", fill: { color: COLORS.white }, color: COLORS.darkText } },
      { text: "C++", options: { align: "left", fill: { color: COLORS.white }, color: COLORS.darkText, bold: true } },
      { text: "—", options: { align: "center", fill: { color: COLORS.lightGray }, color: COLORS.slate } },
      { text: "(2017 winner not in source data)", options: { align: "left", fill: { color: COLORS.lightGray }, color: COLORS.slate, italic: true } },
    ],
    [
      { text: "2021", options: { align: "center", fill: { color: COLORS.lightGray }, color: COLORS.darkText } },
      { text: "Python", options: { align: "left", fill: { color: COLORS.lightGray }, color: COLORS.teal, bold: true } },
      { text: "—", options: { align: "center", fill: { color: COLORS.white }, color: COLORS.slate } },
      { text: "", options: { align: "left", fill: { color: COLORS.white }, color: COLORS.darkText } },
    ],
    [
      { text: "2020", options: { align: "center", fill: { color: COLORS.white }, color: COLORS.darkText } },
      { text: "Python", options: { align: "left", fill: { color: COLORS.white }, color: COLORS.teal, bold: true } },
      { text: "—", options: { align: "center", fill: { color: COLORS.lightGray }, color: COLORS.slate } },
      { text: "", options: { align: "left", fill: { color: COLORS.lightGray }, color: COLORS.darkText } },
    ],
  ];

  slide.addTable(hofRows, {
    x: 0.5, y: 1.35, w: 5.0, h: 2.6,
