const pptxgen = require("pptxgenjs");

// ============================================================
// Color Palette: "Midnight Executive" adapted for data-forward tech
// Primary: 1E2761 (navy), Secondary: CADCFC (ice blue), Accent: FFFFFF (white)
// Additional: 0D9488 (teal for positive), DC2626 (red for negative), 64748B (slate for muted)
// ============================================================
const COLORS = {
  navy: "1E2761",
  iceBlue: "CADCFC",
  white: "FFFFFF",
  teal: "0D9488",
  red: "DC2626",
  slate: "64748B",
  lightGray: "F1F5F9",
  darkText: "1E293B",
  mutedText: "64748B",
  chartBar: "1E2761",
  chartBarSecondary: "CADCFC",
  chartPositive: "0D9488",
  chartNegative: "DC2626",
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "TIOBE Data Analysis";
pres.title = "TIOBE Index March 2026: Programming Language Popularity Rankings and Trends";
pres.subject = "Programming Language Popularity Trends";

// ============================================================
// Helper: fresh shadow factory
// ============================================================
function makeShadow(opts = {}) {
  return {
    type: "outer",
    color: "000000",
    blur: 6,
    offset: 2,
    angle: 135,
    opacity: 0.12,
    ...opts,
  };
}

// ============================================================
// Slide 1: Title
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.navy };

  // Decorative top-right shape (smaller, less intrusive)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 8.0, y: 0, w: 2.0, h: 5.625,
    fill: { color: COLORS.iceBlue, transparency: 10 },
  });

  // Accent bar left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.5, w: 0.08, h: 2.6,
    fill: { color: COLORS.iceBlue },
  });

  // Title
  slide.addText("TIOBE Index March 2026: How 20+ Search Engines Rank the World's Programming Languages", {
    x: 0.75, y: 1.45, w: 7.0, h: 1.5,
    fontSize: 30, fontFace: "Arial Black", color: COLORS.white,
    bold: true, align: "left", valign: "top", margin: 0,
  });

  // Subtitle / methodology
  slide.addText("Ratings calculated from search-engine hit counts across Google, Bing, Wikipedia, Amazon, and 20+ other sites — reflecting global discussion and demand for programming languages.", {
    x: 0.75, y: 3.15, w: 7.5, h: 0.9,
    fontSize: 14, fontFace: "Calibri", color: COLORS.iceBlue,
    align: "left", valign: "top", margin: 0,
  });

  // Footer meta
  slide.addText("Source: TIOBE Programming Community Index  |  Captured: April 2026", {
    x: 0.5, y: 5.15, w: 9, h: 0.3,
    fontSize: 10, fontFace: "Calibri", color: COLORS.iceBlue,
    align: "left", valign: "middle", margin: 0,
  });
}

// ============================================================
// Slide 2: Top 20 Rankings (table + bar chart)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: COLORS.white };

  // Title
  slide.addText("Python Holds #1 at 21.25% but C Surges to #2 with the Largest Gain", {
    x: 0.5, y: 0.25, w: 9, h: 0.6,
    fontSize: 24, fontFace: "Arial Black", color: COLORS.navy,
    bold: true, align: "left", valign: "middle", margin: 0,
  });

  // Subtitle
  slide.addText("Top 20 Programming Languages — March 2026", {
    x: 0.5, y: 0.85, w: 9, h: 0.25,
    fontSize: 12, fontFace: "Calibri", color: COLORS.slate,
    align: "left", valign: "middle", margin: 0,
  });

  // Table data
  const tableRows = [
    [
      { text: "Rank", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "Prev", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "Language", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "left" } },
      { text: "Rating", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
      { text: "YoY Change", options: { bold: true, color: COLORS.white, fill: { color: COLORS.navy }, align: "center" } },
    ],
    ["1", "1", "Python", "21.25%", "-2.59%"],
    ["2", "4", "C", "11.55%", "+2.02%"],
    ["3", "2", "C++", "8.18%", "-2.90%"],
    ["4", "3", "Java", "7.99%", "-2.37%"],
    ["5", "5", "C#", "6.36%", "+1.49%"],
    ["6", "6", "JavaScript", "3.45%", "-0.01%"],
    ["7", "9", "Visual Basic", "2.50%", "-0.02%"],
    ["8", "8", "SQL", "2.00%", "-0.57%"],
    ["9", "16", "R", "1.88%", "+0.94%"],
    ["10", "10", "Delphi/Object Pascal", "1.80%", "-0.36%"],
    ["11", "24", "Perl", "1.75%", "+1.05%"],
    ["12", "12", "Scratch", "1.63%", "-0.03%"],
    ["13", "11", "Fortran", "1.45%", "-0.25%"],
    ["14", "14", "Rust", "1.31%", "+0.09%"],
    ["15", "15", "MATLAB", "1.29%", "+0.31%"],
    ["16", "7", "Go", "1.29%", "-1.49%"],
    ["17", "17", "Assembly language", "1.29%", "+0.42%"],
    ["18", "13", "PHP", "1.23%", "-0.25%"],
    ["19", "18", "Ada", "1.10%", "+0.25%"],
    ["20", "26", "Swift", "1.04%", "+0.44%"],
  ];

  // Colorize YoY cells
  const coloredRows = tableRows.map((row, idx) => {
    if (idx === 0) return row;
    const yoy = row[4];
    const yoyColor = yoy.startsWith("+") ? COLORS.teal : (yoy.startsWith("-") ? COLORS.red : COLORS.darkText);
    const bgColor = idx % 2 === 0 ? COLORS.lightGray : COLORS.white;
    return [
      { text: row[0], options: { align: "center", fill: { color: bgColor }, color: COLORS.darkText } },
      { text: row[1], options: { align: "center", fill: { color: bgColor }, color: COLORS.darkText } },
      { text: row[2], options: { align: "left", fill: { color: bgColor }, color: COLORS.darkText } },
      { text: row[3], options: { align: "center", fill: { color: bgColor }, color: COLORS.darkText } },
      { text: row[4], options: { align: "center", fill: { color: bgColor }, color: yoyColor, bold: true } },
    ];
  });

  slide.addTable(coloredRows, {
    x: 0.5, y: 1.2, w: 5.4, h: 3.9,
    border: { pt: 0.5, color: "E2E8F0" },
    colW: [0.7, 0.7, 2.4, 0.8, 0.8],
    fontSize: 9, fontFace: "Calibri",
    color: COLORS.darkText,
  });

  // Mini bar chart: top 8 languages ratings
  slide.addChart(pres.charts.BAR, [{
